import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { URL } from 'node:url';

const DATA_FILE = path.join(process.cwd(), 'data', 'books.json');
const PORT = process.env.PORT || 3000;

function loadBooks() {
  try {
    if (!fs.existsSync(DATA_FILE)) return [];
    const raw = fs.readFileSync(DATA_FILE, 'utf-8');
    if (!raw.trim()) return [];
    return JSON.parse(raw);
  } catch {
    return [];
  }
}

function saveBooks(books) {
  fs.mkdirSync(path.dirname(DATA_FILE), { recursive: true });
  fs.writeFileSync(DATA_FILE, JSON.stringify(books, null, 2), 'utf-8');
}

function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function escapeHtml(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
*{box-sizing:border-box}body{font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;max-width:860px;margin:0 auto;padding:24px;color:#1a1a1a;background:#fafaf9}
h1{font-size:28px;margin:0 0 8px}
h2{font-size:19px;margin:28px 0 12px;border-bottom:1px solid #e7e5e4;padding-bottom:6px}
.card{border:1px solid #e7e5e4;background:#fff;border-radius:10px;padding:14px 16px;margin:10px 0;display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.card a{color:#2563eb;text-decoration:none;font-weight:600}
.card a:hover{text-decoration:underline}
.meta{color:#57534e;font-size:14px;margin-top:4px}
.badge{font-size:12px;padding:3px 8px;border-radius:999px;background:#f5f5f4;border:1px solid #e7e5e4;white-space:nowrap}
.badge.finished{background:#dcfce7;border-color:#bbf7d0;color:#166534}
.actions{display:flex;gap:8px;align-items:center}
.btn{appearance:none;border:1px solid #d6d3d1;background:#fff;border-radius:8px;padding:8px 12px;cursor:pointer;font-size:14px}
.btn.primary{background:#1c1917;color:#fff;border-color:#1c1917}
.btn:hover{opacity:.9}
form.add{border:1px solid #e7e5e4;background:#fff;border-radius:10px;padding:16px;margin:16px 0}
label{font-size:14px;font-weight:600;display:block;margin:10px 0 4px}
input,textarea{width:100%;padding:9px 10px;border:1px solid #d6d3d1;border-radius:8px;font:inherit}
textarea{min-height:70px;resize:vertical}
.detail{border:1px solid #e7e5e4;background:#fff;border-radius:10px;padding:20px;margin-top:16px}
.detail h1{margin:0}
.detail p{line-height:1.6}
.share{margin-top:14px;padding:10px 12px;background:#f5f5f4;border-radius:8px;font-size:13px;word-break:break-all}
.share a{color:#2563eb}
.empty{color:#78716c;font-size:14px;padding:8px 0}
nav a{color:#57534e;font-size:14px}
</style>
</head>
<body>
${body}
</body>
</html>`;
}

function renderIndex(books) {
  const reading = books.filter(b => b.status !== 'finished');
  const finished = books.filter(b => b.status === 'finished');

  const bookCard = (b) => `
    <div class="card">
      <div>
        <div><a href="/books/${escapeHtml(b.id)}">${escapeHtml(b.title)}</a></div>
        <div class="meta">${escapeHtml(b.author || 'Unknown author')}</div>
        ${b.notes ? `<div class="meta">${escapeHtml(b.notes.length > 120 ? b.notes.slice(0,120)+'…' : b.notes)}</div>` : ''}
      </div>
      <div class="actions">
        <span class="badge ${b.status === 'finished' ? 'finished' : ''}">${b.status === 'finished' ? 'Finished' : 'Reading'}</span>
        ${b.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(b.id)}/finish"><button class="btn" type="submit">Mark finished</button></form>` : ''}
        <a class="btn" href="/books/${escapeHtml(b.id)}">View</a>
      </div>
    </div>`;

  const readingHtml = reading.length ? reading.map(bookCard).join('') : `<div class="empty">Nothing here yet — add a book below.</div>`;
  const finishedHtml = finished.length ? finished.map(bookCard).join('') : `<div class="empty">No finished books yet.</div>`;

  const body = `
  <h1>📚 My Books</h1>
  <nav><p style="margin:4px 0 0;color:#78716c">Track what you're reading. Click a title to see details and share the link.</p></nav>

  <form class="add" method="POST" action="/books">
    <div style="font-weight:700;margin-bottom:8px">Add a book</div>
    <label for="title">Title *</label>
    <input id="title" name="title" required placeholder="e.g. The Hobbit">
    <label for="author">Author</label>
    <input id="author" name="author" placeholder="e.g. J.R.R. Tolkien">
    <label for="notes">Notes</label>
    <textarea id="notes" name="notes" placeholder="What did you think? Keep notes here."></textarea>
    <div style="margin-top:12px"><button class="btn primary" type="submit">Add book</button></div>
  </form>

  <h2>Currently Reading (${reading.length})</h2>
  ${readingHtml}

  <h2>Finished (${finished.length})</h2>
  ${finishedHtml}
  `;

  return layout('My Books', body);
}

function renderDetail(book, origin) {
  const url = origin ? `${origin}/books/${book.id}` : `/books/${book.id}`;
  const body = `
  <nav><a href="/">← Back to all books</a></nav>
  <div class="detail">
    <h1>${escapeHtml(book.title)}</h1>
    <div class="meta" style="margin-top:6px">by ${escapeHtml(book.author || 'Unknown author')}</div>
    <div style="margin-top:8px"><span class="badge ${book.status === 'finished' ? 'finished' : ''}">${book.status === 'finished' ? 'Finished' : 'Currently Reading'}</span></div>
    ${book.notes ? `<div style="margin-top:16px"><div style="font-weight:600;font-size:14px;margin-bottom:6px">Notes</div><p style="white-space:pre-wrap;margin:0">${escapeHtml(book.notes)}</p></div>` : `<p style="color:#78716c;margin-top:16px">No notes yet.</p>`}
    ${book.status !== 'finished' ? `<form method="POST" action="/books/${escapeHtml(book.id)}/finish" style="margin-top:16px"><button class="btn primary" type="submit">Mark as finished</button></form>` : ''}
    <div class="share"><strong>Shareable link:</strong> <a href="${escapeHtml(url)}">${escapeHtml(url)}</a><br><span style="color:#78716c">Send this link to anyone to show this book.</span></div>
  </div>
  `;
  return layout(book.title, body);
}

function parseBody(req) {
  return new Promise(resolve => {
    let data = '';
    req.on('data', chunk => data += chunk);
    req.on('end', () => {
      const ct = req.headers['content-type'] || '';
      if (ct.includes('application/json')) {
        try { resolve(JSON.parse(data || '{}')); } catch { resolve({}); }
      } else if (ct.includes('application/x-www-form-urlencoded') || ct.includes('multipart/form-data') || data.includes('=')) {
        const params = new URLSearchParams(data);
        const obj = {};
        for (const [k, v] of params) obj[k] = v;
        resolve(obj);
      } else if (data) {
        try { resolve(JSON.parse(data)); } catch {
          const params = new URLSearchParams(data);
          if ([...params].length) {
            const obj = {};
            for (const [k,v] of params) obj[k]=v;
            resolve(obj);
          } else resolve({});
        }
      } else resolve({});
    });
  });
}

function wantsJson(req) {
  const accept = req.headers.accept || '';
  const ct = req.headers['content-type'] || '';
  return accept.includes('application/json') || ct.includes('application/json') || req.url.startsWith('/api/');
}

export function createServer() {
  const server = http.createServer(async (req, res) => {
    const url = new URL(req.url, `http://${req.headers.host}`);
    const pathname = url.pathname;
    const method = req.method;

    if (method === 'GET' && (pathname === '/' || pathname === '/index.html')) {
      const books = loadBooks();
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(renderIndex(books));
      return;
    }

    if (method === 'GET' && pathname === '/api/books') {
      const books = loadBooks();
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(books));
      return;
    }

    if (method === 'GET' && pathname.startsWith('/api/books/')) {
      const id = pathname.slice('/api/books/'.length);
      const books = loadBooks();
      const book = books.find(b => b.id === id);
      if (!book) {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Not found' }));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(book));
      return;
    }

    if (method === 'GET' && pathname.startsWith('/books/')) {
      const id = pathname.split('/')[2];
      if (!id) {
        res.writeHead(404, { 'Content-Type': 'text/html' });
        res.end(layout('Not found', '<p>Book not found.</p><a href="/">Back</a>'));
        return;
      }
      const books = loadBooks();
      const book = books.find(b => b.id === id);
      if (!book) {
        res.writeHead(404, { 'Content-Type': 'text/html' });
        res.end(layout('Not found', `<p>Book not found.</p><p><a href="/">← Back to all books</a></p>`));
        return;
      }
      if (wantsJson(req)) {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(book));
        return;
      }
      const origin = `${url.protocol}//${req.headers.host}`;
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(renderDetail(book, origin));
      return;
    }

    if (method === 'POST' && pathname === '/books') {
      const body = await parseBody(req);
      const title = (body.title || '').trim();
      const author = (body.author || '').trim();
      const notes = (body.notes || '').trim();
      if (!title) {
        if (wantsJson(req)) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Title is required' }));
          return;
        } else {
          res.writeHead(400, { 'Content-Type': 'text/html' });
          res.end(layout('Error', '<p>Title is required.</p><a href="/">Back</a>'));
          return;
        }
      }
      const books = loadBooks();
      const book = { id: genId(), title, author, notes, status: 'reading', createdAt: new Date().toISOString() };
      books.push(book);
      saveBooks(books);
      if (wantsJson(req)) {
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(book));
        return;
      }
      res.writeHead(302, { Location: '/' });
      res.end();
      return;
    }

    if (method === 'POST' && pathname === '/api/books') {
      const body = await parseBody(req);
      const title = (body.title || '').trim();
      const author = (body.author || '').trim();
      const notes = (body.notes || '').trim();
      if (!title) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Title is required' }));
        return;
      }
      const books = loadBooks();
      const book = { id: genId(), title, author, notes, status: 'reading', createdAt: new Date().toISOString() };
      books.push(book);
      saveBooks(books);
      res.writeHead(201, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(book));
      return;
    }

    if ((method === 'POST' || method === 'PUT' || method === 'PATCH') && pathname.endsWith('/finish')) {
      const parts = pathname.split('/').filter(Boolean);
      let id;
      if (parts[0] === 'api') id = parts[2];
      else id = parts[1];
      const books = loadBooks();
      const book = books.find(b => b.id === id);
      if (!book) {
        if (wantsJson(req) || pathname.startsWith('/api/')) {
          res.writeHead(404, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Not found' }));
          return;
        } else {
          res.writeHead(404, { 'Content-Type': 'text/html' });
          res.end(layout('Not found', '<p>Book not found.</p><a href="/">Back</a>'));
          return;
        }
      }
      book.status = 'finished';
      book.finishedAt = new Date().toISOString();
      saveBooks(books);
      await parseBody(req).catch(()=>{});
      if (wantsJson(req) || pathname.startsWith('/api/')) {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(book));
        return;
      }
      const referer = req.headers.referer;
      if (referer && referer.includes(`/books/${id}`)) {
        res.writeHead(302, { Location: `/books/${id}` });
      } else {
        res.writeHead(302, { Location: '/' });
      }
      res.end();
      return;
    }

    if (pathname === '/health' || pathname === '/healthz') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: true }));
      return;
    }

    res.writeHead(404, { 'Content-Type': 'text/html' });
    res.end(layout('Not found', '<p>Page not found.</p><a href="/">← Back</a>'));
  });
  return server;
}

const isMain = import.meta.url === `file://${process.argv[1]}` || process.argv[1]?.endsWith('server.js');
if (isMain) {
  const server = createServer();
  server.listen(PORT, () => {
    console.log(`Book tracker listening on http://localhost:${PORT}`);
  });
}

